// DetailsPanel.jsx
import { useState } from 'react';

function CommentBox() {
  const [text, setText] = useState('');
  return <textarea aria-label="Komentarz" value={text} onChange={(e) => setText(e.target.value)} />;
}

export function DetailsPanel({ compact }) {
  if (compact) {
    return (
      <div className="details details--compact">
        <CommentBox />
      </div>
    );
  }
  return (
    <section className="details">
      <CommentBox />
    </section>
  );
}

// DetailsPanel.tsx
import { useState } from 'react';
import clsx from 'clsx';

function CommentBox() {
